function byFrequency(s: string): string {
  const count = new Map<string, number>();
  for (const ch of s) count.set(ch, (count.get(ch) ?? 0) + 1);
  const buckets: string[][] = Array.from({ length: s.length + 1 }, () => []);
  for (const [ch, c] of count) buckets[c].push(ch);
  const parts: string[] = [];
  for (let c = s.length; c >= 1; c--) for (const ch of buckets[c]) parts.push(ch.repeat(c));
  return parts.join("");
}

