class Solution:
    def byFrequency(self, s: str) -> str:
        count = Counter(s)
        buckets = [[] for _ in range(len(s) + 1)]
        for ch, c in count.items():
            buckets[c].append(ch)
        parts = []
        for c in range(len(s), 0, -1):
            for ch in buckets[c]:
                parts.append(ch * c)
        return "".join(parts)

